let current = "en";
export function setTextLang(lang: string) { current = X_TX[lang] ? lang : "en"; }
export function textLang() { return current; }
export function X(key: string, vars?: Record<string, string | number>): string {
  let s = (X_TX[current] && X_TX[current][key]) || X_TX.en[key] || key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}
// Locale for dates: English uses day-month order (en-GB), the others their own language
// Added languages name their own locale; Latin digits everywhere so dates match the numbers the app prints
export function dateLocale(lang = current) { if (lang === "en") return "en-GB"; const m = LANG_META[lang]; return m ? m.locale + "-u-nu-latn" : lang; }
// Right-to-left languages (Arabic, plus any added language that says so)
export function isRtl(lang = current) { return lang === "ar" || LANG_META[lang]?.dir === "rtl"; }

// Short month name in the current language, from the language's own data. Cutting the full name to three letters
// gave "Jui" for both June and July in French, split syllables in Hindi and Bengali, and read "Saturday" in Arabic.
export function monthShort(m: number): string {
  try {
    const d = new Date(2024, m, 15, 12), loc = dateLocale();
    const s = d.toLocaleDateString(loc, { month: "short" });
    if (!/^\d+$/.test(s)) return s;
    // Bulgarian has no short month names in the browser's language data (it answers "06"): use the usual
    // abbreviation, the first three letters of the full name, or the whole name when it is short (март, май, юни)
    const long = [...d.toLocaleDateString(loc, { month: "long" })];
    return long.some(ch => /\d/.test(ch)) ? s : long.length <= 4 ? long.join("") : long.slice(0, 3).join("");
  }
  catch { return ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][m] || ""; }
}
